-- SupplyShield setup | Problem Statement 05
CREATE DATABASE IF NOT EXISTS SUPPLYSHIELD;
CREATE SCHEMA IF NOT EXISTS SUPPLYSHIELD.RAW;
CREATE SCHEMA IF NOT EXISTS SUPPLYSHIELD.CORE;
USE DATABASE SUPPLYSHIELD;
USE SCHEMA RAW;

CREATE OR REPLACE TABLE SUPPLIERS (SUPPLIER_ID STRING PRIMARY KEY,SUPPLIER_NAME STRING,REGION STRING,BASELINE_LEAD_TIME_DAYS NUMBER,RELIABILITY_SCORE NUMBER(5,2),RISK_TIER STRING);
CREATE OR REPLACE TABLE PARTS (PART_ID STRING PRIMARY KEY,PART_NAME STRING,CATEGORY STRING,CRITICALITY STRING,UNIT_COST NUMBER(12,2));
CREATE OR REPLACE TABLE PLANTS (PLANT_ID STRING PRIMARY KEY,PLANT_NAME STRING,CITY STRING,CAPACITY_UNITS NUMBER);
CREATE OR REPLACE TABLE CUSTOMERS (CUSTOMER_ID STRING PRIMARY KEY,CUSTOMER_NAME STRING,SEGMENT STRING);
CREATE OR REPLACE TABLE ORDERS (ORDER_ID STRING PRIMARY KEY,CUSTOMER_ID STRING,PLANT_ID STRING,PART_ID STRING,ORDER_DATE DATE,REQUIRED_DATE DATE,ORDER_QTY NUMBER,PRIORITY STRING);
CREATE OR REPLACE TABLE SHIPMENTS (SHIPMENT_ID STRING PRIMARY KEY,ORDER_ID STRING,SUPPLIER_ID STRING,PART_ID STRING,PROMISED_DATE DATE,ACTUAL_DATE DATE,SHIPPED_QTY NUMBER,STATUS STRING);
CREATE OR REPLACE TABLE INVENTORY (PLANT_ID STRING,PART_ID STRING,ON_HAND_QTY NUMBER,AVG_DAILY_DEMAND NUMBER(12,2),SAFETY_STOCK_QTY NUMBER,SNAPSHOT_DATE DATE,PRIMARY KEY (PLANT_ID,PART_ID));
CREATE OR REPLACE TABLE SUPPLIER_INCIDENTS (INCIDENT_ID STRING PRIMARY KEY,SUPPLIER_ID STRING,INCIDENT_DATE DATE,INCIDENT_TYPE STRING,SEVERITY STRING,DESCRIPTION STRING);

