USE SCHEMA CORE;
CREATE OR REPLACE VIEW V_STOCKOUT_RISK AS
SELECT i.PLANT_ID,p.PLANT_NAME,i.PART_ID,pa.PART_NAME,pa.CATEGORY,pa.CRITICALITY,i.ON_HAND_QTY,i.AVG_DAILY_DEMAND,
ROUND(i.ON_HAND_QTY/NULLIF(i.AVG_DAILY_DEMAND,0),1) DAYS_OF_COVER,
ROUND((i.ON_HAND_QTY-i.SAFETY_STOCK_QTY)/NULLIF(i.AVG_DAILY_DEMAND,0),1) DAYS_TO_SAFETY_STOCK,
i.SAFETY_STOCK_QTY,COUNT_IF(s.STATUS='DELAYED') DELAYED_SHIPMENTS,
COALESCE(MAX(DATEDIFF('day',s.PROMISED_DATE,s.ACTUAL_DATE)),0) MAX_SHIPMENT_DELAY_DAYS,
COUNT(DISTINCT o.ORDER_ID) OPEN_ORDER_COUNT,COALESCE(SUM(o.ORDER_QTY),0) OPEN_ORDER_QTY,
ROUND(LEAST(100,(CASE WHEN i.ON_HAND_QTY/NULLIF(i.AVG_DAILY_DEMAND,0)<5 THEN 40 ELSE 0 END)+(CASE WHEN i.ON_HAND_QTY/NULLIF(i.AVG_DAILY_DEMAND,0)<10 THEN 25 ELSE 0 END)+(CASE WHEN COUNT_IF(s.STATUS='DELAYED')>0 THEN 20 ELSE 0 END)+(CASE WHEN pa.CRITICALITY='CRITICAL' THEN 15 WHEN pa.CRITICALITY='HIGH' THEN 10 ELSE 0 END)),0) RISK_SCORE,
CASE WHEN i.ON_HAND_QTY/NULLIF(i.AVG_DAILY_DEMAND,0)<5 OR (COUNT_IF(s.STATUS='DELAYED')>0 AND pa.CRITICALITY IN ('CRITICAL','HIGH')) THEN 'HIGH' WHEN i.ON_HAND_QTY/NULLIF(i.AVG_DAILY_DEMAND,0)<10 THEN 'MEDIUM' ELSE 'LOW' END RISK_LEVEL
FROM SUPPLYSHIELD.RAW.INVENTORY i JOIN SUPPLYSHIELD.RAW.PARTS pa ON i.PART_ID=pa.PART_ID JOIN SUPPLYSHIELD.RAW.PLANTS p ON i.PLANT_ID=p.PLANT_ID
LEFT JOIN SUPPLYSHIELD.RAW.ORDERS o ON o.PLANT_ID=i.PLANT_ID AND o.PART_ID=i.PART_ID AND o.REQUIRED_DATE>=CURRENT_DATE()
LEFT JOIN SUPPLYSHIELD.RAW.SHIPMENTS s ON s.ORDER_ID=o.ORDER_ID
GROUP BY i.PLANT_ID,p.PLANT_NAME,i.PART_ID,pa.PART_NAME,pa.CATEGORY,pa.CRITICALITY,i.ON_HAND_QTY,i.AVG_DAILY_DEMAND,i.SAFETY_STOCK_QTY;

CREATE OR REPLACE VIEW V_SUPPLIER_PERFORMANCE AS
SELECT s.SUPPLIER_ID,s.SUPPLIER_NAME,s.REGION,s.RELIABILITY_SCORE,s.RISK_TIER,COUNT(sh.SHIPMENT_ID) SHIPMENT_COUNT,
ROUND(AVG(IFF(sh.ACTUAL_DATE<=sh.PROMISED_DATE,100,0)),1) ON_TIME_DELIVERY_RATE,
ROUND(AVG(DATEDIFF('day',sh.PROMISED_DATE,sh.ACTUAL_DATE)),1) AVG_DELAY_DAYS,
COUNT_IF(sh.STATUS='DELAYED') DELAYED_SHIPMENT_COUNT,COUNT(DISTINCT si.INCIDENT_ID) RECENT_INCIDENTS
FROM SUPPLYSHIELD.RAW.SUPPLIERS s LEFT JOIN SUPPLYSHIELD.RAW.SHIPMENTS sh ON s.SUPPLIER_ID=sh.SUPPLIER_ID
LEFT JOIN SUPPLYSHIELD.RAW.SUPPLIER_INCIDENTS si ON s.SUPPLIER_ID=si.SUPPLIER_ID AND si.INCIDENT_DATE>=DATEADD('day',-30,CURRENT_DATE())
GROUP BY s.SUPPLIER_ID,s.SUPPLIER_NAME,s.REGION,s.RELIABILITY_SCORE,s.RISK_TIER;

CREATE OR REPLACE VIEW V_DOWNSTREAM_IMPACT AS
SELECT r.PLANT_ID,r.PLANT_NAME,r.PART_ID,r.PART_NAME,r.RISK_LEVEL,r.RISK_SCORE,s.SUPPLIER_ID,s.SUPPLIER_NAME,s.RISK_TIER,
o.ORDER_ID,o.CUSTOMER_ID,c.CUSTOMER_NAME,c.SEGMENT,o.ORDER_QTY,o.REQUIRED_DATE,o.PRIORITY,sh.SHIPMENT_ID,sh.PROMISED_DATE,sh.ACTUAL_DATE,sh.STATUS,
DATEDIFF('day',sh.PROMISED_DATE,sh.ACTUAL_DATE) DELAY_DAYS
FROM SUPPLYSHIELD.CORE.V_STOCKOUT_RISK r JOIN SUPPLYSHIELD.RAW.ORDERS o ON o.PLANT_ID=r.PLANT_ID AND o.PART_ID=r.PART_ID
JOIN SUPPLYSHIELD.RAW.CUSTOMERS c ON c.CUSTOMER_ID=o.CUSTOMER_ID LEFT JOIN SUPPLYSHIELD.RAW.SHIPMENTS sh ON sh.ORDER_ID=o.ORDER_ID
LEFT JOIN SUPPLYSHIELD.RAW.SUPPLIERS s ON s.SUPPLIER_ID=sh.SUPPLIER_ID WHERE o.REQUIRED_DATE>=CURRENT_DATE();

SELECT * FROM SUPPLYSHIELD.CORE.V_STOCKOUT_RISK ORDER BY RISK_SCORE DESC;